#include "dma_channel_config.h"

/***********************************************************************************************************************
 * STATIC FUNCTION DECLARATION
 **********************************************************************************************************************/
/**
 * @brief Static function to initialize a Linked List for a specific DMA channel and update DMA transactions of the DMA module
 * as per the configuration made in the GUI.
 * @param handle Pointer to static content of DMA channel APP configuration.
 * @return DMA_CHANNEL_CONFIG_STATUS_t: Status of the DMA channel initialization.\n
 *   @ref DMA_CHANNEL_CONFIG_STATUS_SUCCESS - on successful initialization.\n
 *   @ref DMA_CHANNEL_CONFIG_STATUS_FAILURE - if initialization fails.\n
 */
static DMA_CHANNEL_CONFIG_STATUS_t DMA_CHANNEL_CONFIG_LinkedListInit(DMA_CHANNEL_CONFIG_t *handle);

/**********************************************************************************************************************
 * API IMPLEMENTATION
 **********************************************************************************************************************/

ACS_APP_VERSION_t DMA_CHANNEL_CONFIG_GetAppVersion(void)
{
  ACS_APP_VERSION_t version;

  version.major = DMA_CHANNEL_CONFIG_MAJOR_VERSION;
  version.minor = DMA_CHANNEL_CONFIG_MINOR_VERSION;
  version.patch = DMA_CHANNEL_CONFIG_PATCH_VERSION;

  return version;
}

DMA_CHANNEL_CONFIG_STATUS_t DMA_CHANNEL_CONFIG_Init(DMA_CHANNEL_CONFIG_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));

  DMA_CHANNEL_CONFIG_STATUS_t status = DMA_CHANNEL_CONFIG_STATUS_SUCCESS;

  if (!handle->app_is_initialized)
  {
    if (DMA_GENERIC_Init(handle->dma_generic_handle) == DMA_GENERIC_STATUS_SUCCESS)
    {
      handle->app_config->lld_config->module = handle->dma_generic_handle->dma_handle;

      if (handle->app_config->src != NULL_PTR)
      {
#if (DMA_CHANNEL_CONFIG_TCX == DMA_CHANNEL_CONFIG_TC3)
        IfxSrc_init(handle->app_config->src, IfxSrc_Tos_dma, handle->app_config->lld_config->channelId);
#else
        /* In TC4xx, SRC initialization for DMA as type of service does not need a valid virtual machine number; therefore, pass 0 as an argument */
        IfxSrc_init(handle->app_config->src, handle->dma_generic_handle->src_tos, handle->app_config->lld_config->channelId, 0);
#endif
        IfxSrc_enable(handle->app_config->src);
      }

      if (handle->app_config->lld_config->requestSource == IfxDma_ChannelRequestSource_daisyChain)
      {
        /* Giving permission to start the transaction when the daisy chain request pops up */
        IfxDma_Dma_startChannelTransaction(handle->dma_channel_handle);
      }

      /* Check for any kind of Linked List Operation */
      if (handle->app_config->lld_config->shadowControl == IfxDma_ChannelShadow_linkedList ||
          handle->app_config->lld_config->shadowControl == IfxDma_ChannelShadow_accumulatedLinkedList ||
          handle->app_config->lld_config->shadowControl == IfxDma_ChannelShadow_safeLinkedList ||
          handle->app_config->lld_config->shadowControl == IfxDma_ChannelShadow_conditionalLinkedList)
      {
        /* Perform DMA Channel initialization for Linked List Operation */
        DMA_CHANNEL_CONFIG_LinkedListInit(handle);
      }
      else
      {
        /* Initialize the DMA module of the specified DMA channel with GUI-configured parameters */
        IfxDma_Dma_initChannel(handle->dma_channel_handle, handle->app_config->lld_config);
      }

#if (DMA_CHANNEL_CONFIG_TCX == DMA_CHANNEL_CONFIG_TC4)
      /* Channel Interrupt Wait for Write Configuration */
      handle->dma_channel_handle->dma->TSR->B.WWC = handle->app_config->wwc_config;
#endif

      /* Enable Swap Data Byte if it is enabled in Configuration */
      if (handle->app_config->swap_databyte_config)
      {
        IfxDma_enableSwapDataByte(handle->dma_channel_handle->dma, handle->dma_channel_handle->channelId);
      }

#if (DMA_CHANNEL_CONFIG_TCX == DMA_CHANNEL_CONFIG_TC4)
      /* Configure DMA channel Suspend for SUSREQ signal */
      IfxDma_setChannelSuspendEnable(handle->dma_channel_handle->dma,
                                     handle->dma_channel_handle->channelId,
                                     handle->app_config->suspen_config);
#endif

      /* Set APP initialized flag to True */
      handle->app_is_initialized = TRUE;
    }
    else
    {
      status = DMA_CHANNEL_CONFIG_STATUS_FAILURE;
    }
  }

  return status;
}

static DMA_CHANNEL_CONFIG_STATUS_t DMA_CHANNEL_CONFIG_LinkedListInit(DMA_CHANNEL_CONFIG_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));

  DMA_CHANNEL_CONFIG_STATUS_t status = DMA_CHANNEL_CONFIG_STATUS_SUCCESS;

  IfxDma_Dma_ChannelConfig* cfg = handle->app_config->linked_list_update(handle->app_config->lld_config, handle->app_config->linked_list_config);

  unsigned short index;

  for (index = 0; index < handle->app_config->num_of_linked_list_nodes ; index++)
  {
    /* Copy TCS configuration into linked list storage */
    IfxDma_Dma_initLinkedListEntry((void *)&handle->app_config->linked_list_config[index], &cfg[index]);

    if (index == 0)
    {
      IfxDma_Dma_initChannel(handle->dma_channel_handle, &cfg[index]);
    }
    else if (handle->app_config->req_type == DMA_CHANNEL_CONFIG_DMA_REQ_TYPE_AUTO)
    {
      handle->app_config->linked_list_config[index].CHCSR.B.SCH = 1;
    }
    else if (handle->app_config->req_type == DMA_CHANNEL_CONFIG_DMA_REQ_TYPE_INDIVI)
    {
      if (handle->app_config->req_type_indivi[index] == DMA_CHANNEL_CONFIG_DMA_REQ_TYPE_AUTO)
      {
        handle->app_config->linked_list_config[index].CHCSR.B.SCH = 1;
      }
    }
    else
    {
      /* HW requests are already configured in the config file, and SW requests do not need configuration at init; they can be requested via API */
    }
  }

  return status;
}

DMA_CHANNEL_CONFIG_STATUS_t DMA_CHANNEL_CONFIG_Run(DMA_CHANNEL_CONFIG_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle != NULL));

  DMA_CHANNEL_CONFIG_STATUS_t status = DMA_CHANNEL_CONFIG_STATUS_SUCCESS;

  if (handle->app_is_initialized)
  {
    /* Request start of DMA channel transaction */
    IfxDma_Dma_startChannelTransaction(handle->dma_channel_handle);
  }
  else
  {
    status = DMA_CHANNEL_CONFIG_STATUS_FAILURE;
  }

  return status;
}

